// domotica/habitacion/conexion → indicador + evento en SQLite
const estado = String(msg.payload).trim().toLowerCase();
const online = estado === 'online';

node.status({ fill: online ? 'green' : 'red', shape: 'dot', text: estado + ' · ' + new Date().toLocaleTimeString() });

// Registrar el cambio en la tabla eventos (solo si cambia, ignora el retenido repetido)
if (context.get('ultimo') !== estado) {
  context.set('ultimo', estado);
  try {
    const { DatabaseSync } = global.get('sqlite');
    const db = new DatabaseSync('/srv/servidor/bases_datos/domotica.db');
    db.exec('PRAGMA busy_timeout=5000;');
    db.prepare('INSERT INTO eventos (nivel, origen, mensaje) VALUES (?, ?, ?)')
      .run(online ? 'info' : 'warning', 'esp32-habitacion', online ? 'ESP32 en línea' : 'ESP32 desconectado (LWT)');
    db.close();
  } catch (e) {
    node.error('SQLite: ' + e.message);
  }
}

msg.payload = online ? '🟢 En línea' : '🔴 Desconectado';
return msg;
